import{_ as c,r as t,o as l,c as i,e as p,a as n,d as a,s as u}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Методология расширения - October CMS - 3.x","titleTemplate":false,"description":"Узнайте об общих методах расширения October CMS.","frontmatter":{"subtitle":"Узнайте об общих методах расширения October CMS."},"headers":[{"level":2,"title":"Расширение через регистрацию плагина","slug":"расширение-через-регистрацию-плагина","link":"#расширение-через-регистрацию-плагина","children":[]},{"level":2,"title":"Расширение через события","slug":"расширение-через-события","link":"#расширение-через-события","children":[{"level":3,"title":"Подписка на события","slug":"подписка-на-события","link":"#подписка-на-события","children":[]},{"level":3,"title":"Объявление / Генерация событий","slug":"объявление-генерация-событии","link":"#объявление-генерация-событии","children":[]}]},{"level":2,"title":"Расширение представлений панели управления","slug":"расширение-представлении-панели-управления","link":"#расширение-представлении-панели-управления","children":[]},{"level":2,"title":"Примеры использования","slug":"примеры-использования","link":"#примеры-использования","children":[{"level":3,"title":"Расширение модели пользователя","slug":"расширение-модели-пользователя","link":"#расширение-модели-пользователя","children":[]},{"level":3,"title":"Расширение форм панели управления","slug":"расширение-форм-панели-управления","link":"#расширение-форм-панели-управления","children":[]},{"level":3,"title":"Расширение списка панели управления","slug":"расширение-списка-панели-управления","link":"#расширение-списка-панели-управления","children":[]},{"level":3,"title":"Расширение компонента","slug":"расширение-компонента","link":"#расширение-компонента","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/extend/extending.md","filePath":"3.x/ru/extend/extending.md"}'),r={name:"3.x/ru/extend/extending.md"};function k(d,s,g,m,h,v){const e=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[p(e),s[0]||(s[0]=n("h1",null,"Методология расширения",-1)),p(o),s[1]||(s[1]=n("h2",{id:"расширение-через-регистрацию-плагина"},[n("a",{href:"#расширение-через-регистрацию-плагина",class:"header-anchor"},"#"),a(" Расширение через регистрацию плагина")],-1)),s[2]||(s[2]=n("p",null,[a("Практически во всех ситуациях расширение October CMS происходит в файле регистрации плагина, который по сути является "),n("a",{href:"https://laravel.com/docs/10.x/providers",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("сервис-провайдером Laravel"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(". Файл регистрации называется "),n("strong",null,"Plugin.php"),a(" и находится в корневой директории плагина.")],-1)),s[3]||(s[3]=u(`<p>Следующие методы расширения доступны для переопределения в классе регистрации плагина:</p><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><strong>register()</strong></td><td>вызывается при первой регистрации плагина, вызывается перед <code>boot</code>.</td></tr><tr><td><strong>boot()</strong></td><td>вызывается непосредственно перед маршрутизацией запроса, вызывается после <code>register</code>.</td></tr><tr><td><strong>registerMarkupTags()</strong></td><td>регистрирует <a href="./twig-tags.html">дополнительные теги разметки</a>, которые могут использоваться в CMS.</td></tr><tr><td><strong>registerComponents()</strong></td><td>регистрирует любые <a href="./cms-components.html">CMS-компоненты</a>, используемые этим плагином.</td></tr><tr><td><strong>registerNavigation()</strong></td><td>регистрирует <a href="./backend/navigation.html">элементы навигации панели управления</a> для этого плагина.</td></tr><tr><td><strong>registerPermissions()</strong></td><td>регистрирует любые <a href="./backend/permissions.html">разрешения панели управления</a>, используемые этим плагином.</td></tr><tr><td><strong>registerSettings()</strong></td><td>регистрирует любые <a href="./settings/settings.html">ссылки конфигурации панели управления</a>, используемые этим плагином.</td></tr><tr><td><strong>registerFormWidgets()</strong></td><td>регистрирует любые <a href="./forms/form-widgets.html">виджеты форм панели управления</a>, предоставляемые этим плагином.</td></tr><tr><td><strong>registerReportWidgets()</strong></td><td>регистрирует любые <a href="./backend/report-widgets.html">виджеты отчётов панели управления</a>, включая виджеты дашборда.</td></tr><tr><td><strong>registerListColumnTypes()</strong></td><td>регистрирует любые <a href="./lists/list-controller.html">пользовательские типы столбцов списка</a>, предоставляемые этим плагином.</td></tr><tr><td><strong>registerMailTemplates()</strong></td><td>регистрирует любые <a href="./system/sending-mail.html">шаблоны почтовых представлений</a>, предоставляемые этим плагином.</td></tr><tr><td><strong>registerMailLayouts()</strong></td><td>регистрирует любые <a href="./system/sending-mail.html">макеты почтовых представлений</a>, предоставляемые этим плагином.</td></tr><tr><td><strong>registerMailPartials()</strong></td><td>регистрирует любые <a href="./system/sending-mail.html">частичные почтовые представления</a>, предоставляемые этим плагином.</td></tr><tr><td><strong>registerSchedule()</strong></td><td>регистрирует <a href="./system/scheduling.html">запланированные задачи</a>, выполняемые на регулярной основе.</td></tr><tr><td><strong>registerContentFields()</strong></td><td>регистрирует <a href="./../extend/tailor-fields.html">контентные поля</a>, используемые чертежами Tailor.</td></tr></tbody></table></div><h2 id="расширение-через-события"><a href="#расширение-через-события" class="header-anchor">#</a> Расширение через события</h2><p><a href="./services/event.html">Сервис событий</a> является основным способом инъекции или модификации функциональности классов ядра или других плагинов. Этот сервис может быть импортирован для использования в любом классе путём добавления <code>use Event</code> в начало вашего PHP-файла (после объявления пространства имён) для импорта фасада Event.</p><h3 id="подписка-на-события"><a href="#подписка-на-события" class="header-anchor">#</a> Подписка на события</h3><p>Наиболее распространённое место для подписки на событие — метод <code>boot</code> файла регистрации плагина. Например, когда пользователь впервые регистрируется, вы можете захотеть добавить его в сторонний список рассылки — это можно сделать, подписавшись на глобальное событие <code>rainlab.user.register</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.user.register&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token comment">// Code to register $user-&gt;email to mailing list</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Того же можно добиться, расширив конструктор модели и используя локальное событие.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.register&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Code to register $model-&gt;email to mailing list</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="объявление-генерация-событии"><a href="#объявление-генерация-событии" class="header-anchor">#</a> Объявление / Генерация событий</h3><p>Генерируйте локальные события, вызывая <code>fireEvent()</code> на экземпляре объекта, реализующего <code>October\\Rain\\Support\\Traits\\Emitter</code>. Поскольку локальные события генерируются только для конкретного экземпляра объекта, нет необходимости добавлять пространство имён, так как менее вероятно, что в проекте будет несколько событий с одинаковым именем, генерируемых на одних и тех же объектах в локальном контексте.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Глобальные события генерируются вызовом <code>Event::fire()</code>. Поскольку эти события являются глобальными для всего приложения, лучшей практикой является добавление пространства имён, включающего информацию о разработчике в название события. Если автор вашего плагина — ACME, а имя плагина — Blog, то любые глобальные события, предоставляемые плагином ACME.Blog, должны иметь префикс <code>acme.blog</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если одновременно предоставляются и глобальные, и локальные события, лучшей практикой является генерация локального события перед глобальным, чтобы локальное событие имело приоритет. Кроме того, глобальное событие должно предоставлять экземпляр объекта, на котором было сгенерировано локальное событие, в качестве первого параметра.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.blog.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>После подписки на это событие параметры доступны в методе обработчика. Например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Global</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$param1</span><span class="token punctuation">,</span> <span class="token variable">$param2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;posted. Parameters: &#39;</span> <span class="token operator">.</span> <span class="token variable">$param1</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; &#39;</span> <span class="token operator">.</span> <span class="token variable">$param2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Local</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$param1</span><span class="token punctuation">,</span> <span class="token variable">$param2</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;posted. Parameters: &#39;</span> <span class="token operator">.</span> <span class="token variable">$param1</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; &#39;</span> <span class="token operator">.</span> <span class="token variable">$param2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="расширение-представлении-панели-управления"><a href="#расширение-представлении-панели-управления" class="header-anchor">#</a> Расширение представлений панели управления</h2><p>Иногда вам может потребоваться разрешить расширение файла представления или частичного представления панели управления, например панели инструментов. Это возможно с помощью метода <code>fireViewEvent</code>, доступного во всех контроллерах панели управления.</p><p>Поместите этот код в ваш файл представления:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>footer-area-extension<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireViewEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.auth.extendSigninView&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Это позволит другим плагинам внедрять HTML в эту область, подключаясь к событию и возвращая нужную разметку.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.auth.extendSigninView&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">,</span> <span class="token variable">$firstParam</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;&lt;a href=&quot;#&quot;&gt;Sign in with Google!&lt;/a&gt;&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Первый параметр в обработчике события всегда будет вызывающим объектом (контроллером).</p></div><p>Приведённый выше пример выведет следующую разметку:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>footer-area-extension<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>#<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Sign in with Google!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="примеры-использования"><a href="#примеры-использования" class="header-anchor">#</a> Примеры использования</h2><p>Вот несколько практических примеров использования событий.</p><h3 id="расширение-модели-пользователя"><a href="#расширение-модели-пользователя" class="header-anchor">#</a> Расширение модели пользователя</h3><p>Этот пример модифицирует событие <code>model.getAttribute</code> модели <code>User</code>, привязываясь к её локальному событию. Это выполняется внутри метода <code>boot</code> файла регистрации плагина. В обоих случаях при обращении к атрибуту <code>$model-&gt;foo</code> будет возвращено значение <strong>bar</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Local event hook that affects all users</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.getAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Double event hook that affects user #2 only</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.afterFetch&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">id</span> <span class="token operator">!==</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>

        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.getAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для добавления валидации модели для введённых полей подключитесь к событию <code>beforeValidate</code> и выбросьте исключение <code>ValidationException</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeValidate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">billing_first_name</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;billing_first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;First name is required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="расширение-форм-панели-управления"><a href="#расширение-форм-панели-управления" class="header-anchor">#</a> Расширение форм панели управления</h3><div class="custom-block aside"><p>Существует несколько способов расширения форм панели управления, подробнее см. в <a href="./forms/form-controller.html">статье о контроллере форм</a>.</p></div><p>Этот пример прослушивает глобальное событие <code>backend.form.extendFields</code> виджета <code>Backend\\Widget\\Form</code> и внедряет дополнительные поля, когда виджет формы используется для модификации пользователя. Это событие также подписывается внутри метода <code>boot</code> файла регистрации плагина.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Extend all backend form usage</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.form.extendFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Only apply this listener when the Users controller is being used</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Only apply this listener when the User model is being modified</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">model</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Only apply this listener when the Form widget in question is a root-level</span>
    <span class="token comment">// Form widget (not a repeater, nestedform, etc)</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">isNested</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add an extra birthday field</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;birthday&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Birthday&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Select the users birthday&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;datepicker&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Remove a Surname field</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeField</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;surname&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Вы также можете использовать событие <code>backend.form.extendFieldsBefore</code> для добавления полей.</p></div><h3 id="расширение-списка-панели-управления"><a href="#расширение-списка-панели-управления" class="header-anchor">#</a> Расширение списка панели управления</h3><p>Этот пример модифицирует глобальное событие <code>backend.list.extendColumns</code> класса <code>Backend\\Widget\\Lists</code> и внедряет дополнительные значения столбцов при условии, что список используется для модификации пользователя. Это событие также подписывается внутри метода <code>boot</code> файла регистрации плагина.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Extend all backend list usage</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Only for the User controller</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Only for the User model</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">model</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add an extra birthday column</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">addColumns</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;birthday&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Birthday&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Remove a Surname column</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;surname&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="расширение-компонента"><a href="#расширение-компонента" class="header-anchor">#</a> Расширение компонента</h3><p>Этот пример объявляет новое глобальное событие <code>rainlab.forum.topic.post</code> и локальное событие <code>topic.post</code> внутри компонента <code>Topic</code>. Это выполняется в <a href="./cms-components.html">определении класса компонента</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Topic</span> <span class="token keyword">extends</span> <span class="token class-name">ComponentBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onPost</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>

        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;topic.post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$postUrl</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.forum.topic.post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$postUrl</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Далее демонстрируется, как подключиться к этому новому событию из <a href="./../cms/themes/layouts.html">жизненного цикла выполнения макета</a>. Это запишет в журнал трассировки, когда обработчик события <code>onPost</code> вызывается внутри компонента <code>Topic</code> (выше).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">topic</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">slug</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :slug }}</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">topic</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;topic.post&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$postUrl</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token function">trace_log</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;A post has been submitted at &#39;</span><span class="token operator">.</span><span class="token variable">$postUrl</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./services/event.html">Сервис событий</a></li></ul></div>`,49))])}const y=c(r,[["render",k]]);export{b as __pageData,y as default};
